import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { createPrivateKey, createPublicKey, diffieHellman, generateKeyPairSync, randomBytes } from 'node:crypto';
import { createFrameCrypto, deriveSessionKeys } from '../src/security/session.js';

// Emits interop vectors for the Android crypto layer, generated by the
// hub's REAL session code — if the Kotlin side matches these, the phone and
// hub speak the same crypto. Output: android/app/src/test/resources/.

const pcStatic = generateKeyPairSync('x25519');
const deviceStatic = generateKeyPairSync('x25519');
const pcEphemeral = generateKeyPairSync('x25519');
const deviceEphemeral = generateKeyPairSync('x25519');
const salt = randomBytes(32);

const rawPublic = (publicKey: { export(options: { type: 'spki'; format: 'der' }): Buffer }) =>
  publicKey.export({ type: 'spki', format: 'der' }).subarray(-32);
const rawPrivate = (privateKey: { export(options: { type: 'pkcs8'; format: 'der' }): Buffer }) =>
  privateKey.export({ type: 'pkcs8', format: 'der' }).subarray(-32);

// Server-side derivation (what the hub does).
const serverKeys = deriveSessionKeys({
  ownStaticPrivate: pcStatic.privateKey,
  peerStaticPublic: deviceStatic.publicKey,
  ownEphemeralPrivate: pcEphemeral.privateKey,
  peerEphemeralPublic: deviceEphemeral.publicKey,
  salt,
});

const serverCrypto = createFrameCrypto(serverKeys.serverToClient, serverKeys.clientToServer);
const clientCrypto = createFrameCrypto(serverKeys.clientToServer, serverKeys.serverToClient);

const serverPlaintext = '{"hello":"from the hub","n":1}';
const clientPlaintext = '{"type":"hello","client":"mobile","name":"vector-test"}';

const serverFrame = JSON.parse(serverCrypto.seal(serverPlaintext)) as { n: string; c: string };
const clientFrame = JSON.parse(clientCrypto.seal(clientPlaintext)) as { n: string; c: string };

const vectors = {
  pcStaticPrivateRawB64: rawPrivate(pcStatic.privateKey).toString('base64'),
  pcStaticPublicRawB64: rawPublic(pcStatic.publicKey).toString('base64'),
  deviceStaticPrivateRawB64: rawPrivate(deviceStatic.privateKey).toString('base64'),
  deviceStaticPublicRawB64: rawPublic(deviceStatic.publicKey).toString('base64'),
  pcEphemeralPublicRawB64: rawPublic(pcEphemeral.publicKey).toString('base64'),
  deviceEphemeralPrivateRawB64: rawPrivate(deviceEphemeral.privateKey).toString('base64'),
  deviceEphemeralPublicRawB64: rawPublic(deviceEphemeral.publicKey).toString('base64'),
  saltB64: salt.toString('base64'),
  clientToServerKeyB64: serverKeys.clientToServer.toString('base64'),
  serverToClientKeyB64: serverKeys.serverToClient.toString('base64'),
  serverPlaintext,
  serverFrameN: serverFrame.n,
  serverFrameC: serverFrame.c,
  clientPlaintext,
  expectedClientFrameN: clientFrame.n,
  expectedClientFrameC: clientFrame.c,
};

const here = dirname(fileURLToPath(import.meta.url));
const outPath = resolve(here, '../../../android/app/src/test/resources/session-vectors.json');
mkdirSync(dirname(outPath), { recursive: true });
writeFileSync(outPath, JSON.stringify(vectors, null, 2));
console.log(`vectors written: ${outPath}`);
